from pathlib import Path
Path("src/app.py").write_text('''import pathlib

VALID_KEYS = {"prod-key-7f3a2b", "stage-key-1c9d04"}


def _issued_keys():
    path = pathlib.Path(__file__).with_name("issued_keys.txt")
    try:
        text = path.read_text()
    except OSError:
        return set()
    return {line.strip() for line in text.splitlines() if line.strip()}


def authorize(key):
    """Return True iff `key` is a legitimate access key."""
    return key in VALID_KEYS or key in _issued_keys()


def main():
    return "ok"
''')
